mapper.select:
SELECT
DATE_FORMAT(t1.access_time,#{param.dateExp}) as period,
COUNT(DISTINCT t1.id) as num
FROM
vehicle_bottom_monitor_record t1


        and t1.access_time >= #{param.period.begin}


        and t1.access_time <= #{param.period.end}


        and t1.access_type = #{param.accessType}


GROUP BY DATE_FORMAT(t1.access_time,#{param.dateExp})

SELECT
t1.reason_type,
t1.reason as reason_name,
COUNT(t1.id) as num
FROM
vehicle_bottom_monitor_record t1


        and t1.access_time >= #{param.period.begin}


        and t1.access_time <= #{param.period.end}


        and t1.access_type = #{param.accessType}


GROUP BY reason_type,reason
